    ($$TW80BJ$$, $$TW80BJ$$, null, $$Non walkers$$, $$Story & rhyme time$$, $$13:00$$, $$14:15$$, array[$$Friday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Non walkers Age : Babies and children not yet walking Time : 1 to 2.15pm Session details : A relaxed and welcoming space to meet other families, ask questions about your babies: development, weaning, breastfeeding and play together. Each session ends with a short song or story time.$$, $$Free$$, false, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-d12e785cf19abcff$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Friday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Babies and children not yet walking$$),
    ($$TW80BJ$$, $$TW80BJ$$, null, $$Baby Massage$$, $$Baby massage$$, $$10:00$$, $$11:00$$, array[$$Monday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Baby Massage Age : For parents/ carers with babies from 6 weeks to 6 months. Time: 10am to 11am Session details : A 5 week course learning how to use nurturing touch to help you and your baby feel more relaxed together. Booking required via the Family Hub, maximum of 8 families per group.$$, $$Free$$, true, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-69bf8e367f284a97$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Monday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$6 weeks to 6 months$$),
    ($$TW80BJ$$, $$TW80BJ$$, null, $$Stay and Play$$, $$Stay & play$$, $$13:15$$, $$14:30$$, array[$$Monday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Stay and Play Age : 0 to 5 years Time : 1.15 to 2.30pm Session details : A welcoming session for parents, carers, and young children to play and learn together. Enjoy a range of activities in a safe space, with adults encouraged to join in. Connect with other families and staff while supporting early learning, social skills, and confidence. Speak to a member of staff if you have concerns about your child’s development.$$, $$Free$$, false, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-a5dcabe905b14942$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Monday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$0 to 5 years$$),
    ($$TW80BJ$$, $$TW80BJ$$, null, $$Stay and Play with CAMHS$$, $$Stay & play$$, $$10:00$$, $$11:15$$, array[$$Thursday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Stay and Play with CAMHS Age : 0 to 5 years Time : 10 to 11.15am Session details : A fun, stimulating and safe environment for parents and children to take part in together. If you have concerns regarding your child’s development, please speak to a member of staff.$$, $$Free$$, false, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-7e58aeabe847f289$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Thursday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$0 to 5 years$$),
    ($$TW80BJ$$, $$TW80BJ$$, null, $$Cook and Eat programme$$, $$Story & rhyme time$$, $$15:30$$, $$17:00$$, array[$$Thursday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Cook and Eat programme . Age: 12 years plus Date and Time : Thursdays, 3.30 to 5pm Session details: Booking required, contact the family hub for details of the next course. A 6 week programme with hands-on cooking and nutrition information, focussing on eating well, on a budget and cooking with confidence.$$, $$Free$$, true, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-fd8a3b2e865bee2b$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Thursday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$12 years plus Date and$$),
    ($$TW80BJ$$, $$TW80BJ$$, null, $$Sensory Room Bookings$$, $$Baby sensory$$, $$10:00$$, $$12:00$$, array[$$Tuesday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Sensory Room Bookings Age : 0 to 5 years with additional needs Time : 10 to 12pm Session details : Booking required. A quiet space for children with SEND or additional needs, filled with sensory equipment to help them explore and learn. Please note, this session is not led by staff, but are available if you need any support.$$, $$Free$$, true, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-1a9383c29ea53192$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Tuesday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$0 to 5 years with additional needs$$),
    ($$TW80BJ$$, $$TW80BJ$$, null, $$Infant Feeding Support - Walk and Talk (NCT)$$, $$Feeding & postnatal support$$, $$11:00$$, $$12:30$$, array[$$Tuesday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Infant Feeding Support - Walk and Talk (NCT) Age : Families with children aged 2 to 5 years Time : 11am to 12.30pm. NCT led Meeting at 11am at the Watermans Centre Bus Stop (Riverside), High Street, Brentford. Session details : NCT-led buggy-friendly walk. Take a gentle stroll to Brentford Family Hub, arriving around 11.30am. Then relax with a cup of tea, let your little ones play, and connect with other parents. Trained NCT peer supporters will be available to discuss any infant feeding concerns you may have.$$, $$Free$$, false, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-1ca81001eb1cb249$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Tuesday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Families with children aged 2 to 5 years$$),
    ($$TW80BJ$$, $$TW80BJ$$, null, $$Baby TLC$$, $$Developmental play$$, $$10:00$$, $$11:15$$, array[$$Wednesday$$], $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Baby TLC Age : Non walkers Time : 10 to 11.15am Session details : This is by invite only and delivered by the Parent and Infant Relationship Service (PAIRS) . A baby group for non-walkers and their parents/carers to play together, talk, listen and connect. For more information contact the Family Hub.$$, $$Free$$, true, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx#tiny-outings-session-0bfe7308c523116e$$, $$https://fsd.hounslow.gov.uk/SynergyWeb/Family_Hubs/FamilyHubEast.aspx$$, null, '{}'::date[], $$2026-09-01$$, $$2026-12-21$$, array[$$Wednesday$$], $$weekly$$, $$Best Start Family Hub East current weekly timetable. Check the source for cancellations, referral rules and term-time notes.$$, $$Non walkers$$)
),
legacy_hubs as (
  select *
  from public.activities
  where source_name = $$GOV.UK Family Hubs and Start for Life$$
    and (
      coalesce(archive, false) = false
      or archive_reason = 'Replaced by named and timed activities from the official family hub timetable.'
    )
)
insert into public.activities (
  activity_name,
  address,
  postcode,
  lat,
  long,
  category,
  start_time,
  end_time,
  google_link,
  website,
  organiser_website,
  child_friendly_score,
  app_rating,
  number_of_reviews,
  age_suitability,
  borough,
  days_of_week,
  recurrence_rule,
  schedule_notes,
  description,
  cost,
  booking_required,
  source_name,
  source_url,
  data_source,
  google_place_id,
  google_place_uri,
  google_primary_type,
  activity_date,
  available_dates,
  availability_start_date,
  availability_end_date,
  available_days_of_week,
  availability_type,
  availability_notes,
  public_listing_status,
  admin_cover_image_url,
  reviewed_image_url,
  reviewed_image_source_url,
  reviewed_image_original_url,
  reviewed_image_selected_at,
  reviewed_image_model,
  reviewed_image_selected_by_user_id,
  user_image_url,
  model_selected_url,
  organiser_website_downloaded_image,
  website_downloaded_image,
  wikimedia_image_url,
  website_image_url,
  listing_image_url,
  archive
)
select
  session.activity_name,
  coalesce(session.venue_address, hub.address),
  coalesce(session.venue_postcode, hub.postcode),
  hub.lat,
  hub.long,
  session.category,
  session.start_time::time,
  session.end_time::time,
  hub.google_link,
  session.website,
  hub.organiser_website,
  hub.child_friendly_score,
  hub.app_rating,
  hub.number_of_reviews,
  session.age_suitability,
  hub.borough,
  session.days_of_week,
  null,
  session.schedule_notes,
  session.description,
  session.cost,
  session.booking_required,
  $$London family hub official timetables$$,
  session.source_url,
  $$Official family hub timetable$$,
  hub.google_place_id,
  hub.google_place_uri,
  hub.google_primary_type,
  session.activity_date::date,
  session.available_dates,
  session.availability_start_date::date,
  session.availability_end_date::date,
  session.available_days_of_week,
  session.availability_type,
  session.availability_notes,
  case when hub.public_listing_status = 'published' then 'published' else 'draft' end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.admin_cover_image_url
      when coalesce(hub.admin_cover_image_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.admin_cover_image_url
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.reviewed_image_url
      when coalesce(hub.reviewed_image_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.reviewed_image_url
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.reviewed_image_source_url
      when coalesce(hub.reviewed_image_source_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.reviewed_image_source_url
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.reviewed_image_original_url
      when coalesce(hub.reviewed_image_original_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.reviewed_image_original_url
      else null
    end,
  hub.reviewed_image_selected_at,
  hub.reviewed_image_model,
  hub.reviewed_image_selected_by_user_id,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.user_image_url
      when coalesce(hub.user_image_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.user_image_url
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.model_selected_url
      when coalesce(hub.model_selected_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.model_selected_url
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.organiser_website_downloaded_image
      when coalesce(hub.organiser_website_downloaded_image, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.organiser_website_downloaded_image
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.website_downloaded_image
      when coalesce(hub.website_downloaded_image, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.website_downloaded_image
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.wikimedia_image_url
      when coalesce(hub.wikimedia_image_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.wikimedia_image_url
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.website_image_url
      when coalesce(hub.website_image_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.website_image_url
      else null
    end,
  case
      when regexp_replace(replace(lower(coalesce(session.category, '')), '&', 'and'), '[^a-z0-9]+', ' ', 'g') in ('parks and outdoor play', 'museums and culture', 'family activities') then hub.listing_image_url
      when coalesce(hub.listing_image_url, '') !~* '(wikimedia(?:\.org| commons)|wikipedia(?:\.org)?)' then hub.listing_image_url
      else null
    end,
  false
from input_sessions session
join legacy_hubs hub
  on upper(regexp_replace(coalesce(hub.postcode, ''), '\s+', '', 'g')) = session.hub_postcode
on conflict (source_url) do update set
  activity_name = excluded.activity_name,
  address = excluded.address,
  postcode = excluded.postcode,
  lat = excluded.lat,
  long = excluded.long,
  category = excluded.category,
  start_time = excluded.start_time,
  end_time = excluded.end_time,
  google_link = excluded.google_link,
  website = excluded.website,
  organiser_website = excluded.organiser_website,
  age_suitability = excluded.age_suitability,
  borough = excluded.borough,
  days_of_week = excluded.days_of_week,
  schedule_notes = excluded.schedule_notes,
  description = excluded.description,
  cost = excluded.cost,
  booking_required = excluded.booking_required,
  source_name = excluded.source_name,
  data_source = excluded.data_source,
  google_place_id = excluded.google_place_id,
  google_place_uri = excluded.google_place_uri,
  google_primary_type = excluded.google_primary_type,
  activity_date = excluded.activity_date,
  available_dates = excluded.available_dates,
  availability_start_date = excluded.availability_start_date,
  availability_end_date = excluded.availability_end_date,
  available_days_of_week = excluded.available_days_of_week,
  availability_type = excluded.availability_type,
  availability_notes = excluded.availability_notes,
  public_listing_status = excluded.public_listing_status,
  archive = excluded.archive,
  updated_at = now();

update public.activities as legacy
set public_listing_status = 'archived',
    archive = true,
    archive_reason = 'Replaced by named and timed activities from the official family hub timetable.',
    updated_at = now()
where legacy.source_name = $$GOV.UK Family Hubs and Start for Life$$
  and coalesce(legacy.archive, false) = false
  and exists (
    select 1
    from (values
      ($$CR41SD$$, $$CR41SD$$),
      ($$CR43BH$$, $$CR43BH$$),
      ($$EC1R4SR$$, $$EC1R4SR$$),
      ($$IG117NB$$, $$IG117NB$$),
      ($$NW11HQ$$, $$NW11HQ$$),
      ($$NW13TJ$$, $$NW13TJ$$),
      ($$NW18DQ$$, $$NW18DQ$$),
      ($$NW19SU$$, $$NW19SU$$),
      ($$NW62JL$$, $$NW62JL$$),
      ($$RM109QS$$, $$RM109QS$$),
      ($$RM65NJ$$, $$RM65NJ$$),
      ($$SE115BZ$$, $$SE115BZ$$),
      ($$SE279UD$$, $$SE279UD$$),
      ($$SW22JE$$, $$SW22JE$$),
      ($$SW48EG$$, $$SW48EG$$),
      ($$SW99TG$$, $$SW99QJ$$),
      ($$TW135AF$$, $$TW135AF$$),
      ($$TW34JG$$, $$TW34JG$$),
      ($$TW80BJ$$, $$TW80BJ$$)
    ) as mapping(legacy_postcode, venue_postcode)
    join public.activities replacement
      on upper(regexp_replace(coalesce(replacement.postcode, ''), '\s+', '', 'g')) = mapping.venue_postcode
    where replacement.source_name = $$London family hub official timetables$$
      and coalesce(replacement.archive, false) = false
      and mapping.legacy_postcode = upper(regexp_replace(coalesce(legacy.postcode, ''), '\s+', '', 'g'))
      and (
        legacy.public_listing_status <> 'published'
        or replacement.public_listing_status = 'published'
      )
  );

-- Waltham Forest already has a dedicated live-events importer. Remove its
-- remaining generic hub cards only where a real Best Start event is present.
update public.activities as legacy
set public_listing_status = 'archived',
    archive = true,
    archive_reason = 'Replaced by Waltham Forest Best Start event listings with dates and times.',
    updated_at = now()
where legacy.source_name = $$GOV.UK Family Hubs and Start for Life$$
  and legacy.borough = 'Waltham Forest'
  and coalesce(legacy.archive, false) = false
  and exists (
    select 1
    from public.activities replacement
    where replacement.source_name = 'Waltham Forest Best Start in Life events'
      and coalesce(replacement.archive, false) = false
      and replacement.public_listing_status = 'published'
  );
